import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

export type DestroyCustomKeyVariables = {id: number}

export function destroyCustomKeyMutationOptions(
  org: string,
): UseMutationOptions<void, ResponseError, DestroyCustomKeyVariables> {
  return {
    async mutationFn({id}) {
      const res = await reactFetchJSON(`/organizations/${org}/settings/custom-keys/${id}`, {
        method: 'DELETE',
      })
      if (!res.ok) {
        const resp = await res.json()
        throw new ResponseError(String(resp.message) || 'Failed to delete custom key', res)
      }
    },
  }
}
