import {createContext, type PropsWithChildren, use} from 'react'
import invariant from 'tiny-invariant'

const CurrentOrgContext = createContext<string | null>(null)

export function CurrentOrgProvider({children, value}: PropsWithChildren<{value: string}>) {
  return <CurrentOrgContext value={value}>{children}</CurrentOrgContext>
}

export function useCurrentOrg() {
  const org = use(CurrentOrgContext)
  invariant(org, 'useCurrentOrg must be used within a CurrentOrgProvider')
  return org
}
