import {CheckIcon, PencilIcon, XIcon} from '@primer/octicons-react'
import {IconButton, TextInput} from '@primer/react'
import {type KeyboardEventHandler, type PropsWithChildren, useCallback, useEffect, useRef, useState} from 'react'

import styles from './InlineEdit.module.css'

/*
NOTE; This component has not been built as a general-purpose inline edit solution,
it may work for your use-case, and if so, great. It was built for the ModelSelector
*/
export function InlineEdit({
  'aria-describedby': ariaDescribedby,
  children,
  defaultValue,
  placeholderValue,
  enabled,
  onSave,
}: PropsWithChildren<{
  'aria-describedby'?: string
  defaultValue?: string
  placeholderValue?: string
  enabled: boolean
  onSave?: (newValue: string) => void
}>) {
  const [editing, setEditing] = useState(false)

  const inputRef = useRef<HTMLInputElement>(null)
  const returnFocusRef = useRef<HTMLButtonElement>(null)

  const returnFocus = useCallback(() => {
    globalThis.requestAnimationFrame(() => {
      returnFocusRef?.current?.focus()
    })
  }, [])

  // If we edit, select the input so the user can start typing
  useEffect(() => {
    if (editing && inputRef.current) {
      globalThis.requestAnimationFrame(() => {
        inputRef.current?.select()
      })
    }
  }, [editing])

  const cancel = useCallback(() => {
    setEditing(false)
    returnFocus()
  }, [returnFocus])

  const save = useCallback(() => {
    if (!inputRef.current || !onSave) return void cancel()
    const newValue = inputRef.current.value
    onSave(newValue)
    returnFocus()
    setEditing(false)
  }, [onSave, cancel, returnFocus])

  const handleKeyDown = useCallback<KeyboardEventHandler<HTMLInputElement>>(
    event => {
      if (event.target !== inputRef.current) return

      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      switch (event.key) {
        case 'Enter':
          {
            event.preventDefault()
            save()
          }
          break
        case 'Escape': {
          event.preventDefault()
          cancel()
        }
      }
    },
    [save, cancel],
  )

  if (!enabled) return <>{children}</>

  return (
    <div className={styles.InlineEdit}>
      {editing ? (
        <TextInput
          ref={inputRef}
          defaultValue={defaultValue}
          placeholder={placeholderValue}
          size="small"
          className="width-full"
          aria-label="Edit value"
          aria-describedby={ariaDescribedby}
          onKeyDown={handleKeyDown}
        />
      ) : (
        children
      )}
      <div className={styles.ActionsContainer}>
        {editing && (
          <>
            <IconButton
              icon={XIcon}
              variant="default"
              size="small"
              aria-label="Cancel edit"
              aria-describedby={ariaDescribedby}
              onClick={cancel}
            />
            <IconButton
              icon={CheckIcon}
              variant="default"
              size="small"
              aria-label="Save edits"
              aria-describedby={ariaDescribedby}
              onClick={save}
            />
          </>
        )}
        {!editing && (
          <IconButton
            ref={returnFocusRef}
            icon={PencilIcon}
            variant="invisible"
            size="small"
            aria-label="Edit"
            aria-describedby={ariaDescribedby}
            onClick={() => setEditing(true)}
          />
        )}
      </div>
    </div>
  )
}
